freezeBadge.useItemEffect:
(function () {
	var success = false;

	var snowFourDirections = false; // 是否多方向雪花；如果是将其改成true
	if (snowFourDirections) {
		// 多方向雪花
		for (var direction in core.utils.scan) { // 多方向雪花默认四方向，如需改为八方向请将这两个scan改为scan2
			var delta = core.utils.scan[direction];
			var nx = core.getHeroLoc('x') + delta.x,
				ny = core.getHeroLoc('y') + delta.y;
			if (core.getBlockId(nx, ny) == 'lava') {
				core.removeBlock(nx, ny);
				success = true;
			}
		}
	} else {
		if (core.getBlockId(core.nextX(), core.nextY()) == 'lava') {
			core.removeBlock(core.nextX(), core.nextY());
			success = true;
		}
	}

	if (success) {
		core.playSound('打开界面');
		core.drawTip(core.material.items[itemId].name + '使用成功', itemId);
	} else {
		core.playSound('操作失败');
		core.drawTip("当前无法使用" + core.material.items[itemId].name, itemId);
		core.addItem(itemId, 1);
		return;
	}
})();

