pickaxe.useItemEffect:
(function () {
	var canBreak = function (x, y) {
		var block = core.getBlock(x, y);
		if (block == null || block.disable) return false;
		if (core.getFlag('pzf', 0) == 1) {
			if (core.status.thisMap.floorId == 'MT10' || core.status.thisMap.floorId == 'MT11' || core.status.thisMap.floorId == 'MT12' || core.status.thisMap.floorId == 'MT13' || core.status.thisMap.floorId == 'MT14' || core.status.thisMap.floorId == 'MT15' || core.status.thisMap.floorId == 'MT16' || core.status.thisMap.floorId == 'MT17' || core.status.thisMap.floorId == 'MT18' || core.status.thisMap.floorId == 'MT19' || core.status.thisMap.floorId == 'MT20' || core.status.thisMap.floorId == 'MT26') {
				if (block.id == 4) return true;
				if (block.event.cls == 'tileset') return true;
			}
		}
		return block.event.canBreak;
	};

	var success = false;
	var pickaxeFourDirections = false; // 是否多方向破；如果是将其改成true
	if (pickaxeFourDirections) {
		// 多方向破
		for (var direction in core.utils.scan) { // 多方向破默认四方向，如需改成八方向请将这两个scan改为scan2
			var delta = core.utils.scan[direction];
			var nx = core.getHeroLoc('x') + delta.x,
				ny = core.getHeroLoc('y') + delta.y;
			if (canBreak(nx, ny)) {
				core.removeBlock(nx, ny);
				success = true;
			}
		}
	} else {
		// 仅破当前
		if (canBreak(core.nextX(), core.nextY())) {
			core.removeBlock(core.nextX(), core.nextY());
			success = true;
		}
	}

	if (success) {
		core.playSound('破墙镐');
		core.drawTip(core.material.items[itemId].name + '使用成功', itemId);
	} else {
		// 无法使用
		core.playSound('操作失败');
		core.drawTip("当前无法使用" + core.material.items[itemId].name, itemId);
		core.addItem(itemId, 1);
		return;
	}
})();

bomb.useItemEffect:
(function () {
	var bombList = []; // 炸掉的怪物坐标列表
	var todo = []; // 炸弹后事件
	var money = 0,
		exp = 0; // 炸弹获得的金币和经验

	var canBomb = function (x, y) {
		var block = core.getBlock(x, y);
		if (block == null || block.disable || block.event.cls.indexOf('enemy') != 0) return false;
		var enemy = core.material.enemys[block.event.id];
		return enemy && !enemy.notBomb;
	};

	var bomb = function (x, y) {
		if (!canBomb(x, y)) return;
		bombList.push([x, y]);
		var id = core.getBlockId(x, y),
			enemy = core.material.enemys[id];
		money += core.getEnemyValue(enemy, 'money', x, y) || 0;
		exp += core.getEnemyValue(enemy, 'exp', x, y) || 0;
		core.push(todo, core.floors[core.status.floorId].afterBattle[x + "," + y]);
		core.push(todo, enemy.afterBattle);
		core.removeBlock(x, y);
	}

	// 如果要多方向可炸，把这里的false改成true
	if (true) {
		var scan = core.utils.scan; // 多方向炸时默认四方向，如果要改成八方向炸可以改成 core.utils.scan2
		for (var direction in scan) {
			var delta = scan[direction];
			bomb(core.getHeroLoc('x') + delta.x, core.getHeroLoc('y') + delta.y);
		}
	} else {
		// 仅炸当前
		bomb(core.nextX(), core.nextY());
	}

	if (bombList.length == 0) {
		core.playSound('操作失败');
		core.drawTip('当前无法使用' + core.material.items[itemId].name, itemId);
		core.addItem(itemId, 1);
		return;
	}

	//core.playSound('炸弹');
	core.drawHeroAnimate('bomb'); //播放动画
	core.screenFlash([255, 255, 0, 1], 1300); //画面闪烁
	core.drawTip(core.material.items[itemId].name + '使用成功', itemId);

	// 取消这里的注释可以炸弹后获得金币和经验
	// core.status.hero.money += money;
	// core.status.hero.exp += exp;

	// 取消这里的注释可以炸弹引发战后事件
	if (todo.length > 0) core.insertAction(todo);

})();

