earthquake.useItemEffect:
(function () {
	var indexes = [];
	for (var index in core.status.thisMap.blocks) {
		var block = core.status.thisMap.blocks[index];
		if (!block.disable && block.event.canBreak) {
			indexes.push(index);
		}
	}
	core.removeBlockByIndexes(indexes);
	core.redrawMap();
	core.playSound('炸弹');
	core.drawTip(core.material.items[itemId].name + '使用成功');
})();

