skill1.useItemEffect:
(function () {
	var skillValue = 1; // 技能的flag:skill值，可用于当前开启技能的判定；对于新技能可以依次改成2，3等等
	var skillNeed = 5; // 技能的需求
	var skillName = '二倍斩'; // 技能的名称

	if (core.getFlag('skill', 0) != skillValue) { // 判断当前是否已经开了技能
		if (core.getStatus('mana') >= skillNeed) { // 这里要写当前能否开技能的条件判断，比如魔力值至少要多少
			core.playSound('打开界面');
			core.setFlag('skill', skillValue); // 开技能1
			core.setFlag('skillName', skillName); // 设置技能名
		} else {
			core.playSound('操作失败');
			core.drawTip('魔力不足，无法开启技能');
		}
	} else { // 关闭技能
		core.setFlag('skill', 0); // 关闭技能状态
		core.setFlag('skillName', '无');
	}
})();

